package in.sevasetu.amc.web;
import in.sevasetu.amc.security.CurrentUser;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import org.springframework.web.server.ResponseStatusException;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.sql.Timestamp;import java.time.Instant;import java.util.*;
@RestController @RequestMapping("/api/delivery") public class DeliveryController{private final JdbcClient db;private static final String FALLBACK="987600";public DeliveryController(JdbcClient db){this.db=db;}
 public record Request(boolean whatsappOptOut){} public record OtpResult(String status,String maskedMobile,String fallbackOtp,Instant expiresAt){} public record Confirm(@NotBlank String otp){} public record Page(List<Map<String,Object>> content,int page,int totalPages,long totalElements){}
 @PostMapping("/orders/{id}/request-otp") @Transactional OtpResult request(@AuthenticationPrincipal CurrentUser u,@PathVariable UUID id,@RequestBody(required=false) Request r){CustomerController.tenant(u);var row=db.sql("select c.id customer_id,c.phone,o.fulfillment_status,(coalesce(s.whatsapp_enabled,false) and coalesce((select enabled from amcservice.tenant_feature_entitlements f where f.tenant_id=o.tenant_id and f.feature_code='WHATSAPP'),false)) whatsapp_enabled from amcservice.orders o join amcservice.customers c on c.id=o.customer_id left join amcservice.tenant_automation_settings s on s.tenant_id=o.tenant_id where o.id=:id and o.tenant_id=:t").param("id",id).param("t",u.tenantId()).query().listOfRows().stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Bill not found"));if("DELIVERED".equals(row.get("fulfillment_status")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Order is already delivered");boolean optOut=r!=null&&r.whatsappOptOut();var expires=Instant.now().plusSeconds(600);db.sql("insert into amcservice.order_delivery_otps(order_id,tenant_id,otp_hash,whatsapp_opt_out,expires_at,requested_by) values(:o,:t,:hash,:optout,:expires,:u) on conflict(order_id) do update set otp_hash=excluded.otp_hash,whatsapp_opt_out=excluded.whatsapp_opt_out,attempts=0,expires_at=excluded.expires_at,verified_at=null,requested_by=excluded.requested_by,created_at=now()").param("o",id).param("t",u.tenantId()).param("hash",hash(FALLBACK)).param("optout",optOut).param("expires",Timestamp.from(expires)).param("u",u.userId()).update();var phone=String.valueOf(row.get("phone"));var whatsapp=Boolean.TRUE.equals(row.get("whatsapp_enabled"));if(whatsapp&&!optOut)db.sql("insert into amcservice.notification_jobs(id,tenant_id,customer_id,kind,scheduled_for,status,message,idempotency_key) values(:id,:t,:c,'DELIVERY_OTP',now(),'PENDING',:message,:key) on conflict(idempotency_key) do update set scheduled_for=now(),status='PENDING',message=excluded.message,sent_at=null").param("id",UUID.randomUUID()).param("t",u.tenantId()).param("c",row.get("customer_id")).param("message","Your delivery verification OTP is "+FALLBACK+". It expires in 10 minutes.").param("key",u.tenantId()+":delivery-otp:"+id).update();var status=optOut?"CUSTOMER_OPTED_OUT_FALLBACK":whatsapp?"WHATSAPP_PENDING_FALLBACK_AVAILABLE":"WHATSAPP_NOT_CONFIGURED_FALLBACK";return new OtpResult(status,mask(phone),FALLBACK,expires);}
 @PostMapping("/orders/{id}/confirm") @Transactional void confirm(@AuthenticationPrincipal CurrentUser u,@PathVariable UUID id,@Valid@RequestBody Confirm r){CustomerController.tenant(u);var otp=db.sql("select otp_hash,attempts,expires_at<now() expired from amcservice.order_delivery_otps where order_id=:o and tenant_id=:t for update").param("o",id).param("t",u.tenantId()).query().listOfRows().stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,"Request an OTP first"));if(Boolean.TRUE.equals(otp.get("expired")))throw new ResponseStatusException(HttpStatus.GONE,"OTP expired. Request a new one");if((Integer)otp.get("attempts")>=5)throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"Too many OTP attempts");if(!MessageDigest.isEqual(hash(r.otp()).getBytes(StandardCharsets.UTF_8),String.valueOf(otp.get("otp_hash")).getBytes(StandardCharsets.UTF_8))){db.sql("update amcservice.order_delivery_otps set attempts=attempts+1 where order_id=:o").param("o",id).update();throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Incorrect OTP");}db.sql("update amcservice.order_delivery_otps set verified_at=now() where order_id=:o").param("o",id).update();db.sql("update amcservice.orders set fulfillment_status='DELIVERED',delivered_at=now(),completed_at=coalesce(completed_at,now()),updated_at=now() where id=:o and tenant_id=:t").param("o",id).param("t",u.tenantId()).update();var bill=db.sql("select o.bill_number,o.customer_id,(coalesce(s.whatsapp_enabled,false) and coalesce((select enabled from amcservice.tenant_feature_entitlements f where f.tenant_id=o.tenant_id and f.feature_code='WHATSAPP'),false)) whatsapp_enabled from amcservice.orders o left join amcservice.tenant_automation_settings s on s.tenant_id=o.tenant_id where o.id=:o and o.tenant_id=:t").param("o",id).param("t",u.tenantId()).query().listOfRows().getFirst();if(Boolean.TRUE.equals(bill.get("whatsapp_enabled")))db.sql("insert into amcservice.notification_jobs(id,tenant_id,customer_id,kind,scheduled_for,status,message,idempotency_key) values(:id,:t,:c,'FINAL_BILL',now(),'PENDING',:message,:key) on conflict(idempotency_key) do nothing").param("id",UUID.randomUUID()).param("t",u.tenantId()).param("c",bill.get("customer_id")).param("message","Your final bill "+bill.get("bill_number")+" is ready. The secure PDF link will be added when bill streaming is enabled.").param("key",u.tenantId()+":final-bill:"+id).update();}
 @PostMapping(value="/orders/{id}/media",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @ResponseStatus(HttpStatus.CREATED) void upload(@AuthenticationPrincipal CurrentUser u,@PathVariable UUID id,@RequestPart("files")List<MultipartFile> files)throws Exception{CustomerController.tenant(u);if(db.sql("select count(*) from amcservice.orders where id=:o and tenant_id=:t and fulfillment_status='DELIVERED'").param("o",id).param("t",u.tenantId()).query(Integer.class).single()==0)throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,"Verify delivery before uploading media");if(files.isEmpty()||files.size()>10)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Upload up to 10 images or reels");for(var f:files){var type=Optional.ofNullable(f.getContentType()).orElse("");var limit=type.startsWith("video/")?30_000_000:5_000_000;if((!type.startsWith("image/")&&!type.startsWith("video/"))||f.getSize()>limit)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Images must be under 5 MB and reels under 30 MB");db.sql("insert into amcservice.order_delivery_media(id,tenant_id,order_id,file_name,content_type,file_size,media_data,uploaded_by) values(:id,:t,:o,:name,:type,:size,:data,:u)").param("id",UUID.randomUUID()).param("t",u.tenantId()).param("o",id).param("name",Optional.ofNullable(f.getOriginalFilename()).orElse("delivery-media")).param("type",type).param("size",f.getSize()).param("data",f.getBytes()).param("u",u.userId()).update();}}
 @GetMapping("/gallery") Page gallery(@AuthenticationPrincipal CurrentUser u,@RequestParam(defaultValue="0")@Min(0)int page){CustomerController.tenant(u);var total=db.sql("select count(*) from amcservice.order_delivery_media m join amcservice.orders o on o.id=m.order_id where m.tenant_id=:t and o.fulfillment_status='DELIVERED'").param("t",u.tenantId()).query(Long.class).single();var rows=db.sql("select m.id,m.order_id,m.file_name,m.content_type,m.file_size,m.favorite,m.created_at,o.bill_number,c.name customer_name from amcservice.order_delivery_media m join amcservice.orders o on o.id=m.order_id join amcservice.customers c on c.id=o.customer_id where m.tenant_id=:t and o.fulfillment_status='DELIVERED' order by m.favorite desc,m.created_at desc limit 8 offset :offset").param("t",u.tenantId()).param("offset",page*8).query().listOfRows();return new Page(rows,page,(int)Math.ceil(total/8.0),total);}
 @PatchMapping("/gallery/{id}/favorite") void favorite(@AuthenticationPrincipal CurrentUser u,@PathVariable UUID id,@RequestParam boolean value){CustomerController.tenant(u);if(db.sql("update amcservice.order_delivery_media set favorite=:v where id=:id and tenant_id=:t").param("v",value).param("id",id).param("t",u.tenantId()).update()==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Gallery item not found");}
 @GetMapping("/gallery/{id}/content") ResponseEntity<byte[]> content(@AuthenticationPrincipal CurrentUser u,@PathVariable UUID id){CustomerController.tenant(u);return db.sql("select content_type,media_data from amcservice.order_delivery_media where id=:id and tenant_id=:t").param("id",id).param("t",u.tenantId()).query((rs,n)->ResponseEntity.ok().contentType(MediaType.parseMediaType(rs.getString(1))).cacheControl(CacheControl.noStore()).body(rs.getBytes(2))).optional().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Media not found"));}
 private static String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}private static String mask(String p){return p.length()<4?"****":"******"+p.substring(p.length()-4);}
}
